import ast, sys, re

with open('src/wild_data_calibration.py') as f:
    source = f.read()

tree = ast.parse(source)

# Find parse_args function and extract argparse arguments
for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef) and node.name == 'parse_args':
        for child in ast.walk(node):
            if isinstance(child, ast.Call):
                if hasattr(child.func, 'attr') and child.func.attr == 'add_argument':
                    args_strs = [ast.literal_eval(a) for a in child.args if isinstance(a, ast.Constant)]
                    print(f'  {args_strs}')
print('Argparse structure OK')
"
